/**
 * Content checks on the shipped Synvoya seed dataset: what users act on must be well-formed,
 * sourced and comparable. Generated by scripts/build-synvoya-dataset.mjs from the approved seed list.
 */

import { beforeAll, describe, expect, it } from "vitest";

import { loadSynvoyaDataset } from "./dataset.js";
import { cycleOf } from "./evaluate.js";
import type { SynvoyaDataset } from "./types.js";
import { compareVersions, schemeFor } from "./versions.js";

/** Verdict `drop` in the approved 2026-11-03 seed list: never shipped. */
const DROPPED = ["SYN-2026-102", "SYN-2026-132", "SYN-2026-262", "SYN-2026-286", "SYN-2026-316"];

/** MinIO publishes RELEASE.<timestamp> tags only: the vendor fix is not a comparable version (no image maps to it). */
const NOT_COMPARABLE = new Set(["SYN-2026-268", "SYN-2026-276"]);

let dataset: SynvoyaDataset;

beforeAll(async () => {
  const loaded = await loadSynvoyaDataset();
  if (!loaded.ok) throw new Error(loaded.reason);
  dataset = loaded.dataset;
});

describe("shipped Synvoya seed dataset", () => {
  it("ships the approved entries: unique ids and slugs, no dropped id", () => {
    const ids = dataset.advisories.map((a) => a.id);
    const slugs = dataset.advisories.map((a) => a.slug);
    expect(new Set(ids).size).toBe(ids.length);
    expect(new Set(slugs).size).toBe(slugs.length);
    for (const id of DROPPED) {
      // A split part (SYN-2026-062 → SYN-2026-06201) carries its parent id in aliases.
      expect(ids).not.toContain(id);
      expect(dataset.advisories.filter((a) => a.aliases.includes(id))).toEqual([]);
    }
    expect(ids.length).toBeGreaterThan(250);
  });

  it("every entry cites at least one https source", () => {
    for (const advisory of dataset.advisories) {
      expect(advisory.sources.filter((source) => source.startsWith("https://")).length, advisory.id).toBeGreaterThan(0);
    }
  });

  it("a non-provisional entry names a fix, or says why it has none", () => {
    for (const a of dataset.advisories) {
      if (a.provisional || a.fixed.length > 0) continue;
      const why =
        a.kind === "eol" ||
        a.kind === "malware" ||
        a.no_fix_available === true ||
        // A hotfix that never changes the version string (Adobe isolated patches): the finding says verify it.
        (a.product_rule === "verify-hotfix" && a.target.type === "product") ||
        // Config hygiene (mutable action tags) is not versioned; it needs the M2 Actions matcher.
        (a.kind === "config" && a.requires === "M2");
      expect(why, a.id).toBe(true);
    }
  });

  it("no_fix_available appears only with an empty fixed list, on non-provisional vulnerabilities", () => {
    const noFix = dataset.advisories.filter((a) => a.no_fix_available);
    // 05501: code.gitea.io/gitea, whose fix ships only under the renamed module gitea.dev.
    expect(noFix.map((a) => a.id).sort()).toEqual(["SYN-2026-05501", "SYN-2026-056", "SYN-2026-058"]);
    for (const a of noFix) expect(a.fixed).toEqual([]);
  });

  it("split parts follow ecosystem then package name, so a part's id never depends on input order", () => {
    const parts = new Map<string, string[]>();
    for (const a of dataset.advisories) {
      const parent = a.aliases.find((alias) => /^SYN-\d{4}-\d+$/.test(alias) && a.id.startsWith(alias) && a.id !== alias);
      const family = parent ?? a.id;
      if (a.target.type === "package") parts.set(family, [...(parts.get(family) ?? []), `${a.target.ecosystem}\0${a.target.name}`]);
    }
    for (const id of ["SYN-2026-062", "SYN-2026-064", "SYN-2026-065", "SYN-2026-066", "SYN-2026-067", "SYN-2026-083"]) {
      const keys = parts.get(id)!;
      expect(keys.length, id).toBeGreaterThan(1);
      expect(keys, id).toEqual([...keys].sort());
    }
  });

  it("product_rule appears only on product targets", () => {
    for (const a of dataset.advisories) {
      if (a.product_rule !== undefined) expect(a.target.type, a.id).toBe("product");
    }
  });

  it("every Adobe Commerce, Magento, ColdFusion and WebLogic entry is verify-hotfix and names its bulletin where Adobe published one", () => {
    const patchLevel = dataset.advisories.filter(
      (a) => a.target.type === "product" && ["adobe-commerce", "magento-open-source", "coldfusion", "weblogic"].includes(a.target.product),
    );
    expect(patchLevel.length).toBeGreaterThan(30);
    for (const a of patchLevel) {
      expect(a.product_rule, a.id).toBe("verify-hotfix");
      if (a.target.type === "product" && a.target.product !== "weblogic") {
        expect(a.aliases.some((alias) => /^(APSB\d{2}-\d+|VULN-\d+)$/.test(alias)), a.id).toBe(true);
      }
    }
    // WSO2 verify findings name the vendor advisory.
    for (const a of dataset.advisories.filter((x) => x.target.type === "product" && x.target.product === "wso2-api-manager")) {
      expect(a.aliases.some((alias) => /^WSO2-\d{4}-\d+$/.test(alias)), a.id).toBe(true);
    }
  });

  it("titles carry no internal research notes", () => {
    for (const a of dataset.advisories) {
      expect(a.title, a.id).not.toMatch(/last_affected|engine output|alias map|\b4\.0\b|inferred|container image \/ product-version form/);
    }
  });

  it("every range event and line is comparable in its target's version scheme", () => {
    const bad: string[] = [];
    for (const a of dataset.advisories) {
      if (NOT_COMPARABLE.has(a.id)) continue;
      const scheme = schemeFor(a.target);
      for (const element of a.affected) {
        if (element.line !== undefined && !/^\d+(?:\.\d+)*$/.test(element.line)) bad.push(`${a.id} line ${element.line}`);
        for (const event of element.events) {
          const value = Object.values(event)[0] as string;
          if ("introduced" in event && value === "0") continue;
          if (compareVersions(scheme, value, value) === undefined) bad.push(`${a.id} ${scheme} ${value}`);
        }
      }
    }
    expect(bad).toEqual([]);
  });

  it("entries that need a later reader are marked requires: M2 (GitHub Actions, Go stdlib)", () => {
    const m2 = dataset.advisories.filter((a) => a.requires === "M2").map((a) => a.id);
    expect(m2).toContain("SYN-2026-019");
    expect(m2).toContain("SYN-2026-326");
    for (const a of dataset.advisories) {
      if (a.target.type === "package" && a.target.ecosystem === "GitHub Actions") expect(a.requires, a.id).toBe("M2");
    }
  });

  it("titles are plain text: no doubled spaces or dangling words after a colon (SYN-2026-237 was garbled)", () => {
    for (const a of dataset.advisories) {
      expect(a.title, a.id).not.toMatch(/ {2}|: (?:and|or)\b|\s[,:]/);
    }
    expect(dataset.advisories.find((a) => a.id === "SYN-2026-237")!.title).toBe(
      "MongoDB Server: Improper Handling of Length Parameter Inconsistency Vulnerability (KEV 2025-12-29)",
    );
  });

  it("vendor-confirmed fixed releases (php.net ChangeLog-8, re-checked 2026-11-03)", () => {
    const byId = (id: string) => dataset.advisories.find((a) => a.id === id)!;
    // 8.3.36 carries the GHSA-w8hw-w9fx-j79w / GHSA-6wmf-4rv5-p3rp fix on the still-supported 8.3 line.
    expect(byId("SYN-2026-015").fixed).toEqual(["8.2.35", "8.3.36", "8.4.27", "8.5.12"]);
    // The n8n vendor advisory names 1.122.0 only; the 1.120.4 / 1.121.1 backports are NVD/OSV-derived.
    expect(byId("SYN-2026-096").fixed).toEqual(["1.122.0"]);
  });

  it("an advisory with a platform precondition no reader can see waits for platform detection (CVE-2024-4577 is Windows PHP-CGI only)", () => {
    const cgi = dataset.advisories.find((a) => a.id === "SYN-2026-150")!;
    expect(cgi.requires).toBe("platform-detection");
  });

  it("every end-of-life cycle has a date, a latest release and an https source, once per product", () => {
    const seen = new Set<string>();
    for (const entry of dataset.eol) {
      expect(entry.eol, `${entry.product} ${entry.cycle}`).toMatch(/^\d{4}-\d{2}-\d{2}$/);
      expect(entry.latest, `${entry.product} ${entry.cycle}`).toBeTruthy();
      expect(entry.source.startsWith("https://endoflife.date/")).toBe(true);
      const key = `${entry.product}\0${entry.cycle}`;
      expect(seen.has(key), key).toBe(false);
      seen.add(key);
    }
    // Runtime cycles are at the evaluator's granularity, so a declared version finds its line.
    for (const entry of dataset.eol) {
      if (!["node", "php", "python", "ruby", "go", "dotnet", "java"].includes(entry.product)) continue;
      const runtime = entry.product as "node";
      expect(cycleOf({ type: "runtime", runtime }, entry.cycle), `${entry.product} ${entry.cycle}`).toBe(entry.cycle);
    }
    for (const product of ["node", "php", "python", "ruby", "go", "dotnet", "java", "postgres", "postgresql", "mysql", "redis", "mongodb"]) {
      expect(dataset.eol.some((entry) => entry.product === product), product).toBe(true);
    }
  });

  it("every image table entry leads somewhere: an advisory or an end-of-life product", () => {
    const packages = new Set(
      dataset.advisories.flatMap((a) => (a.target.type === "package" ? [`${a.target.ecosystem}:${a.target.name}`] : [])),
    );
    for (const [image, pkg] of Object.entries(dataset.imageAliases)) {
      expect(packages.has(`${pkg.ecosystem}:${pkg.name}`), image).toBe(true);
    }
    const products = new Set([
      ...dataset.advisories.flatMap((a) => (a.target.type === "product" ? [a.target.product] : [])),
      ...dataset.eol.map((entry) => entry.product),
      // Named in the design's product-image list (§10.10); no seeded advisory yet.
      "kestra",
    ]);
    for (const [image, product] of Object.entries(dataset.productImages)) expect(products.has(product), image).toBe(true);
  });
});
